package com.ethk3.novaonepro.r952;

import com.ethk3.novaonepro.Models;
import com.ethk3.novaonepro.TypedAtomMoleculeGraphR930;
import com.ethk3.novaonepro.TargetIssueResolver;
import com.ethk3.novaonepro.RuntimeMemoryGuardR811;
import java.util.*;
import java.util.regex.*;

/** One strict prefix-only Draw-Matrix algorithm shared by SCDEV training and live PIT binding.
 * No current checkpoint or target draw label is read. Non-draw evidence still requires old receipts. */
public final class MatrixHistoricalDrawCP12 {
 private MatrixHistoricalDrawCP12(){}
 private static final Pattern PART=Pattern.compile("position:([1-9]|10)(?:\\|sourcePosition:([1-9]|10))?(?:\\|lag:([1-9][0-9]{0,3}))?(?:\\|regime:([0-4])\\|regimePolicy:([0-9a-f]{64}))?");
 private interface Prefix {int size();String target();String issue(int i);long time(int i);int digit(int i,int p);}
 private static final class Partition {final int position,source,lag,regime;Partition(MatrixBindingsCP12.Ref ref,int p){Matcher m=PART.matcher(ref.partition(p));need(m.matches(),"DRAW_MATRIX_PARTITION");position=Integer.parseInt(m.group(1));source=m.group(2)==null?position:Integer.parseInt(m.group(2));lag=m.group(3)==null?0:Integer.parseInt(m.group(3));regime=m.group(4)==null?-1:Integer.parseInt(m.group(4));if(ref.type==MatrixProjectionCP12.Type.TransitionMatrix||ref.type==MatrixProjectionCP12.Type.ConditionalTransitionMatrix)need(lag>0,"DRAW_MATRIX_LAG_REQUIRED");if(ref.type==MatrixProjectionCP12.Type.ConditionalTransitionMatrix)need(regime>=0&&AtomRegimePolicyCP12.POLICY_HASH.equals(m.group(5)),"DRAW_MATRIX_REGIME_POLICY");}}
 public static boolean isDrawRefCP12(MatrixBindingsCP12.Ref ref){switch(ref.type){case FrequencyMatrix:case OmissionMatrix:case TransitionMatrix:case ConditionalTransitionMatrix:case DriftMatrix:return PART.matcher(ref.partition(1)).matches();default:return false;}}
 public static int minimumHistoryCP12(MatrixBindingsCP12.Ref ref){if(!isDrawRefCP12(ref))return 0;Partition p=new Partition(ref,1);int width=ref.type==MatrixProjectionCP12.Type.DriftMatrix?2*ref.window:ref.window;return width+Math.max(p.lag,ref.type==MatrixProjectionCP12.Type.ConditionalTransitionMatrix?100:0);}
 public static int requiredHistoryCP12(Object canonicalMatrixRefs){int maximum=0;for(Object raw:CandidateAstR952.array(canonicalMatrixRefs)){MatrixBindingsCP12.Ref ref=new MatrixBindingsCP12.Ref(new FeatureManifestR952.MatrixRef(CandidateAstR952.object(raw)));maximum=Math.max(maximum,minimumHistoryCP12(ref));}return maximum;}
 public static int requiredHistoryCP12(FeatureManifestR952 manifest){int maximum=0;for(FeatureManifestR952.MatrixRef raw:manifest.matrixSpecRefs)maximum=Math.max(maximum,minimumHistoryCP12(new MatrixBindingsCP12.Ref(raw)));return maximum;}
 public static boolean requiresStoredReceiptsCP12(CandidateCompilerR952.Program program){return requiresStoredReceiptsCP12(program.ast,program.manifest);}
 public static boolean requiresStoredReceiptsCP12(CandidateAstR952 ast,FeatureManifestR952 manifest){for(MatrixBindingsCP12.Ref ref:MatrixBindingsCP12.validate(ast,manifest))if(!isDrawRefCP12(ref))return true;return false;}
 public static Map<String,TypedAtomMoleculeGraphR930.Value> evaluateCP12(CandidateCompilerR952.Program program,final DevelopmentInputCP9.Input input,final int targetIndex){
  need(input!=null&&targetIndex>0&&targetIndex<input.rowCount(),"DRAW_MATRIX_TRAIN_TARGET");
  Prefix prefix=new Prefix(){public int size(){return targetIndex;}public String target(){return input.issue(targetIndex);}public String issue(int i){need(i>=0&&i<targetIndex,"DRAW_MATRIX_TARGET_LABEL_FORBIDDEN");return input.issue(i);}public long time(int i){need(i>=0&&i<targetIndex,"DRAW_MATRIX_TARGET_LABEL_FORBIDDEN");return input.openTime(i);}public int digit(int i,int p){need(i>=0&&i<targetIndex,"DRAW_MATRIX_TARGET_LABEL_FORBIDDEN");return input.actual(i,p)-1;}};
  Map<String,TypedAtomMoleculeGraphR930.Value> result=new TreeMap<>();for(MatrixBindingsCP12.Ref ref:MatrixBindingsCP12.validate(program.ast,program.manifest))if(isDrawRefCP12(ref)){MatrixSnapshotBusR952.CheckpointCP4 cp=project(ref,program.ast.position,prefix);Selected s=select(ref,program.ast.position,prefix,cp);result.put(ref.node(),new MatrixBindingsCP12.Frozen(ref,ref.partition(program.ast.position),cp,s.value,s.present).atomValue(prefix.time(prefix.size()-1)));}return Collections.unmodifiableMap(result);
 }
 static MatrixSnapshotBusR952.CheckpointCP4 checkpointFromPitCP12(MatrixBindingsCP12.Ref ref,int position,final PITSnapshotContractR952 pit){pit.requireConsecutive();return project(ref,position,new Prefix(){public int size(){return pit.history.size();}public String target(){return pit.targetIssue;}public String issue(int i){return pit.history.get(size()-1-i).issue;}public long time(int i){return pit.history.get(size()-1-i).openTime;}public int digit(int i,int p){return pit.history.get(size()-1-i).getNumberAtPosition(p)-1;}});}
 private static final class Selected {final double value;final boolean present;Selected(double v,boolean p){value=v;present=p;}}
 private static Selected select(MatrixBindingsCP12.Ref ref,int position,Prefix prefix,MatrixSnapshotBusR952.CheckpointCP4 cp){MatrixProjectionCP12.Spec spec=new MatrixProjectionCP12.Spec(ref.type,ref.partition(position),ref.window,ref.manifest);Map<String,double[]> metrics=MatrixProjectionCP12.metrics(MatrixProjectionCP12.decode(spec,cp.payload()));int[] source=ref.metricSourceCP13(position);String metric=MatrixBindingsCP12.resolveMetricCP12(ref.metric,prefix.digit(prefix.size()-source[1],source[0]));String[] pieces=metric.split("~",-1);double[] values=metrics.get(pieces[0]);int index=pieces.length==2?Integer.parseInt(pieces[1]):0;boolean present=values!=null&&index<values.length;return new Selected(present?values[index]:0,present);}
 private static MatrixSnapshotBusR952.CheckpointCP4 project(MatrixBindingsCP12.Ref ref,int position,Prefix prefix){
  need(isDrawRefCP12(ref),"DRAW_MATRIX_TYPE");int required=minimumHistoryCP12(ref);need(required<=5000&&prefix.size()>=required,"WAIT_MATRIX_HISTORY");Partition p=new Partition(ref,position);MatrixProjectionCP12.Spec spec=new MatrixProjectionCP12.Spec(ref.type,ref.partition(position),ref.window,ref.manifest);MatrixProjectionCP12.State state=MatrixProjectionCP12.empty(spec);int width=ref.type==MatrixProjectionCP12.Type.DriftMatrix?2*ref.window:ref.window;int first=prefix.size()-width;
  String proof=MatrixProjectionCP12.hash("CP12_DRAW_MATRIX_PREFIX_V1|"+ref.manifest+'|'+prefix.target()+'|'+ref.partition(position));String previous=null;for(int i=prefix.size()-required;i<prefix.size();i++){String issue=prefix.issue(i);need(issue.compareTo(prefix.target())<0&&(previous==null||TargetIssueResolver.exact(previous,issue).valid),"DRAW_MATRIX_PIT_SEQUENCE");StringBuilder row=new StringBuilder(proof).append('|').append(issue).append('|').append(prefix.time(i));for(int j=1;j<=10;j++){int d=prefix.digit(i,j);need(d>=0&&d<=9,"DRAW_MATRIX_DIGIT");row.append('|').append(d);}proof=MatrixProjectionCP12.hash(row.toString());previous=issue;}need(TargetIssueResolver.exact(previous,prefix.target()).valid,"DRAW_MATRIX_TARGET_GAP");
  AtomWindowCP4 ring=null;try{if(ref.type==MatrixProjectionCP12.Type.ConditionalTransitionMatrix){ring=new AtomWindowCP4(RuntimeMemoryGuardR811.algorithmAtomMatrixBudget());for(int i=first-100;i<first;i++)ring.append(MatrixSourceRouterCP12.issueOrdinal(prefix.issue(i)),prefix.digit(i,p.position));}
   for(int i=first;i<prefix.size();i++){long ordinal=MatrixSourceRouterCP12.issueOrdinal(prefix.issue(i));int regime=p.regime;if(ring!=null){int best=0;double largest=-1;for(int j=0;j<5;j++){AtomEvaluatorCP4.Result r=AtomEvaluatorCP4.evaluate(new AtomEvaluatorCP4.Spec("REGIME_SCORE",50,0,0,0,0,0,0,0,.5,AtomRegimePolicyCP12.LABELS[j]),ring,null,ordinal);need(r.present,"WAIT_REGIME5_HISTORY_PROOF");if(r.value>largest){largest=r.value;best=j;}}regime=best;}
    if(ring==null||regime==p.regime){int actual=prefix.digit(i,p.position),prior=p.lag==0?actual:prefix.digit(i-p.lag,p.source);MatrixProjectionCP12.apply(state,ordinal,new MatrixProjectionCP12.Sample(ordinal,0,ref.type==MatrixProjectionCP12.Type.TransitionMatrix||ref.type==MatrixProjectionCP12.Type.ConditionalTransitionMatrix?prior:actual,actual,ref.type==MatrixProjectionCP12.Type.ConditionalTransitionMatrix?regime:actual,0,0,0,0,0),null);}else MatrixProjectionCP12.advanceThroughCP12(state,ordinal);
    if(ring!=null)ring.append(ordinal,prefix.digit(i,p.position));
   }
  }finally{if(ring!=null)ring.close();}
  String through=prefix.issue(prefix.size()-1);String receipt=MatrixProjectionCP12.hash("CP12_DRAW_MATRIX_REPLAY|"+proof+'|'+spec.matrixId+'|'+through);return new MatrixSnapshotBusR952.CheckpointCP4(ref.type.name(),spec.partition,ref.window,ref.manifest,MatrixProjectionCP12.SCHEMA_HASH,0,through,receipt,state.samples(),MatrixProjectionCP12.encode(state));
 }
 private static void need(boolean value,String code){if(!value)throw new IllegalArgumentException(code);}
}
